
const WORDS=[{"id": 0, "w": "忠实", "p": "zhōngshí", "t": "形容词", "m": "trung thành, chân thực", "coll": "忠实的读者、忠实记录", "s": "这部纪录片忠实地记录了当地居民的日常生活。"}, {"id": 1, "w": "不敢当", "p": "bù gǎndāng", "t": "动词", "m": "không dám nhận (lời khen hoặc sự trọng đãi; cách nói khiêm nhường)", "coll": "实在不敢当、不敢当，您过奖了", "s": "听到大家称赞他是专家，他连忙摆手说：不敢当，我还需要继续学习。"}, {"id": 2, "w": "走廊", "p": "zǒuláng", "t": "名词", "m": "hành lang, hàng hiên", "coll": "教学楼走廊、走廊尽头", "s": "下课以后，请不要在走廊里追逐打闹。"}, {"id": 3, "w": "徒弟", "p": "túdi", "t": "名词", "m": "học trò, đồ đệ", "coll": "收徒弟、带徒弟", "s": "这位老师傅对每个徒弟都十分耐心。"}, {"id": 4, "w": "气功", "p": "qìgōng", "t": "名词", "m": "khí công", "coll": "练气功、气功爱好者", "s": "每天清晨，公园里都有几位气功爱好者一起练习。"}, {"id": 5, "w": "剑", "p": "jiàn", "t": "名词", "m": "thanh gươm, thanh kiếm", "coll": "一把剑、练剑", "s": "演员手持一把剑，在舞台上完成了一套动作。"}, {"id": 6, "w": "哦", "p": "ò", "t": "叹词", "m": "ồ, chà, ôi chao", "coll": "哦，原来如此、哦，我明白了", "s": "哦，原来你说的地方就在学校旁边！"}, {"id": 7, "w": "协会", "p": "xiéhuì", "t": "名词", "m": "hội, hội liên hiệp", "coll": "行业协会、作家协会", "s": "这次交流活动由当地的作家协会主办。"}, {"id": 8, "w": "爆发", "p": "bàofā", "t": "动词", "m": "đột phát, bùng lên", "coll": "爆发掌声、爆发冲突", "s": "演出结束时，观众席上爆发出热烈的掌声。"}, {"id": 9, "w": "劈", "p": "pī", "t": "动词", "m": "bổ, chẻ", "coll": "劈木头、劈成两半", "s": "他举起斧头，把这块木头劈成了两半。"}, {"id": 10, "w": "误解", "p": "wùjiě", "t": "动词／名词", "m": "hiểu lầm, hiểu sai; sự hiểu lầm", "coll": "产生误解、消除误解", "s": "经过耐心解释，双方终于消除了误解。"}, {"id": 11, "w": "群众", "p": "qúnzhòng", "t": "名词", "m": "quần chúng", "coll": "服务群众、群众意见", "s": "制定新措施之前，应该充分听取群众的意见。"}, {"id": 12, "w": "逐年", "p": "zhúnián", "t": "副词", "m": "hằng năm, mỗi năm", "coll": "逐年增长、逐年下降", "s": "随着交通条件改善，来这里旅游的人数逐年增长。"}, {"id": 13, "w": "要素", "p": "yàosù", "t": "名词", "m": "yếu tố", "coll": "关键要素、基本要素", "s": "明确的目标是制定学习计划时不可缺少的要素。"}, {"id": 14, "w": "智力", "p": "zhìlì", "t": "名词", "m": "trí khôn", "coll": "智力发展、智力活动", "s": "这套益智游戏需要参与者运用智力解决各种问题。"}, {"id": 15, "w": "预期", "p": "yùqī", "t": "动词", "m": "dự kiến, kỳ vọng", "coll": "达到预期、预期目标", "s": "经过共同努力，这次活动达到了预期目标。"}, {"id": 16, "w": "首要", "p": "shǒuyào", "t": "形容词", "m": "hàng đầu, quan trọng nhất", "coll": "首要任务、首要条件", "s": "保护现场人员的安全是目前的首要任务。"}, {"id": 17, "w": "生锈", "p": "shēngxiù", "t": "动词", "m": "bị gỉ, gỉ sét", "coll": "铁门生锈、容易生锈", "s": "这扇铁门长期没有维护，已经生锈了。"}, {"id": 18, "w": "放射", "p": "fàngshè", "t": "动词", "m": "phóng ra, phát ra", "coll": "放射光芒、向外放射", "s": "节日的烟花在夜空中绽放，向四周放射出耀眼的光芒。"}, {"id": 19, "w": "夫人", "p": "fūren", "t": "名词", "m": "phu nhân, vợ (cách gọi kính trọng)", "coll": "尊夫人、夫人陪同", "s": "张先生和夫人一起出席了昨晚的音乐会。"}, {"id": 20, "w": "端端正正", "p": "duānduānzhèngzhèng", "t": "形容词", "m": "ngay ngắn, chỉnh tề", "coll": "坐得端端正正、摆得端端正正", "s": "上课铃响后，孩子们都坐得端端正正。"}, {"id": 21, "w": "端正", "p": "duānzhèng", "t": "形容词／动词", "m": "ngay ngắn, đoan chính; chỉnh đốn", "coll": "态度端正、坐姿端正", "s": "学习时态度要端正，遇到不懂的问题应该主动请教。"}, {"id": 22, "w": "潜力", "p": "qiánlì", "t": "名词", "m": "tiềm lực", "coll": "发展潜力、挖掘潜力", "s": "老师鼓励学生尝试不同的任务，充分挖掘自己的潜力。"}, {"id": 23, "w": "衰退", "p": "shuāituì", "t": "动词", "m": "suy yếu, suy thoái", "coll": "经济衰退、功能衰退", "s": "这本书分析了当时经济衰退的原因。"}, {"id": 24, "w": "著作", "p": "zhùzuò", "t": "名词", "m": "tác phẩm", "coll": "学术著作、出版著作", "s": "这位学者花了十年时间，完成了这部重要的学术著作。"}, {"id": 25, "w": "反射", "p": "fǎnshè", "t": "动词", "m": "phản xạ, phản chiếu, bức xạ", "coll": "光的反射、条件反射", "s": "老师通过实验演示了光的反射现象。"}, {"id": 26, "w": "弱点", "p": "ruòdiǎn", "t": "名词", "m": "nhược điểm, điểm yếu", "coll": "发现弱点、克服弱点", "s": "了解自己的弱点，才能有针对性地改进学习方法。"}, {"id": 27, "w": "迁就", "p": "qiānjiù", "t": "动词", "m": "nhân nhượng, chiều theo, chiếu ý", "coll": "一味迁就、互相迁就", "s": "相处时需要互相体谅，但不应一味迁就。"}, {"id": 28, "w": "坚定", "p": "jiāndìng", "t": "形容词", "m": "kiên định, kiên quyết", "coll": "坚定信念、态度坚定", "s": "面对困难，她依然坚定地朝着目标前进。"}, {"id": 29, "w": "坚韧", "p": "jiānrèn", "t": "形容词", "m": "vững chắc, kiên trì", "coll": "坚韧的意志、坚韧不拔", "s": "他凭着坚韧的意志，完成了艰难的长途跋涉。"}, {"id": 30, "w": "狠心", "p": "hěnxīn", "t": "形容词／动词", "m": "nhẫn tâm, cứng lòng; dứt lòng làm điều khó", "coll": "狠心拒绝、不忍狠心", "s": "看着孩子失望的神情，她实在不忍狠心拒绝。"}, {"id": 31, "w": "半途而废", "p": "bàntú'érfèi", "t": "成语", "m": "bỏ dở nửa chừng", "coll": "学习半途而废、不要半途而废", "s": "既然已经决定学习这门技术，就不要半途而废。"}, {"id": 32, "w": "虐待", "p": "nüèdài", "t": "动词", "m": "ngược đãi, hành hạ", "coll": "虐待动物、遭受虐待", "s": "任何人都不应该虐待动物。"}, {"id": 33, "w": "落实", "p": "luòshí", "t": "动词", "m": "thi hành, thực hiện đầy đủ", "coll": "落实措施、落实责任", "s": "会议结束后，各部门立即开始落实相关措施。"}, {"id": 34, "w": "归根到底", "p": "guīgēn dàodǐ", "t": "成语", "m": "suy cho cùng, xét đến cùng", "coll": "归根到底，靠自己、归根到底是态度问题", "s": "归根到底，良好的合作离不开信任和沟通。"}, {"id": 35, "w": "胡乱", "p": "hùluàn", "t": "副词", "m": "qua quýt, tùy tiện", "coll": "胡乱猜测、胡乱花钱", "s": "没有调查清楚之前，不要胡乱猜测事情的原因。"}, {"id": 36, "w": "间接", "p": "jiànjiē", "t": "形容词", "m": "gián tiếp", "coll": "间接影响、间接证据", "s": "这项政策也会对周边地区产生间接影响。"}, {"id": 37, "w": "品行", "p": "pǐnxíng", "t": "名词", "m": "phẩm hạnh, hạnh kiểm", "coll": "品行端正、优良品行", "s": "选拔志愿者时，除了能力，也要考察个人的品行。"}, {"id": 38, "w": "紫外线", "p": "zǐwàixiàn", "t": "名词", "m": "tia tử ngoại, tia cực tím", "coll": "紫外线照射、紫外线强度", "s": "天气预报会提醒市民注意当天的紫外线强度。"}, {"id": 39, "w": "消毒", "p": "xiāodú", "t": "动词", "m": "trừ độc, khử trùng", "coll": "消毒设备、进行消毒", "s": "工作人员按照操作要求，对使用过的器具进行了消毒。"}, {"id": 40, "w": "钙", "p": "gài", "t": "名词", "m": "canxi (calcium)", "coll": "钙含量、钙元素", "s": "学生在实验报告中记录了样品的钙含量。"}, {"id": 41, "w": "二氧化碳", "p": "èryǎnghuàtàn", "t": "名词", "m": "carbon dioxide (CO2)", "coll": "二氧化碳排放、二氧化碳浓度", "s": "这项研究比较了不同交通方式的二氧化碳排放量。"}, {"id": 42, "w": "舒畅", "p": "shūchàng", "t": "形容词", "m": "khoan khoái, dễ chịu", "coll": "心情舒畅、感到舒畅", "s": "与朋友谈过心以后，她的心情舒畅了许多。"}, {"id": 43, "w": "宣扬", "p": "xuānyáng", "t": "动词", "m": "tuyên truyền, truyền bá, đề cao", "coll": "宣扬理念、宣扬美德", "s": "这部作品通过普通人的故事，宣扬了诚实守信的美德。"}, {"id": 44, "w": "孔", "p": "kǒng", "t": "名词", "m": "lỗ, khe hở", "coll": "一个孔、钻孔", "s": "工人按照图纸，在木板上钻了一个孔。"}, {"id": 45, "w": "循序渐进", "p": "xúnxù jiànjìn", "t": "成语", "m": "tiến dần từng bước", "coll": "循序渐进地学习、循序渐进的方法", "s": "学习新知识应该循序渐进，先打好基础，再逐步提高。"}, {"id": 46, "w": "急于求成", "p": "jíyú qiú chéng", "t": "成语", "m": "nóng lòng muốn thành công", "coll": "急于求成的心态、切忌急于求成", "s": "刚开始练习时，不要急于求成，应先掌握基本动作。"}, {"id": 47, "w": "剧烈", "p": "jùliè", "t": "形容词", "m": "dữ dội, mạnh", "coll": "剧烈的变化、剧烈运动", "s": "市场需求发生了剧烈的变化，企业必须及时调整计划。"}, {"id": 48, "w": "幅度", "p": "fúdù", "t": "名词", "m": "mức độ, phạm vi", "coll": "变化幅度、提高幅度", "s": "与上个月相比，本月价格的变化幅度不大。"}, {"id": 49, "w": "蛋白质", "p": "dànbáizhì", "t": "名词", "m": "protein", "coll": "蛋白质含量、蛋白质结构", "s": "食品标签上标出了每份食品的蛋白质含量。"}, {"id": 50, "w": "维生素", "p": "wéishēngsù", "t": "名词", "m": "vitamin", "coll": "维生素含量、维生素种类", "s": "这张表格列出了几种水果中不同维生素的含量。"}, {"id": 51, "w": "不愧", "p": "bùkuì", "t": "副词", "m": "xứng đáng, quả không hổ là", "coll": "不愧是专家、不愧为榜样", "s": "他很快找出了问题的关键，不愧是经验丰富的工程师。"}, {"id": 52, "w": "定期", "p": "dìngqī", "t": "形容词", "m": "định kỳ, theo thời hạn đã định", "coll": "定期检查、定期举行", "s": "图书馆每个月都会定期举行读书交流会。"}, {"id": 53, "w": "联络", "p": "liánluò", "t": "动词", "m": "liên lạc, liên hệ", "coll": "保持联络、主动联络", "s": "毕业以后，我们仍然通过网络保持联络。"}, {"id": 54, "w": "保重", "p": "bǎozhòng", "t": "动词", "m": "giữ gìn sức khỏe", "coll": "多加保重、保重身体", "s": "临别时，她再三叮嘱朋友在外工作要保重身体。"}];
